import{A as e,E as t,d as n,l as r,p as i}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as a}from"./app-ybrB4hSf.js";var o=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/PostgreSQL/01_%E5%9F%BA%E7%A1%80%E7%AF%87/03_%E7%B4%A2%E5%BC%95%E4%BD%93%E7%B3%BB.html","title":"索引体系","lang":"zh-CN","frontmatter":{"title":"索引体系","order":3,"category":["数据库","PostgreSQL"],"tag":["PostgreSQL","索引","B-Tree","GIN","BRIN"]},"git":{"createdTime":1780573763000,"updatedTime":1780573763000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":8.3,"words":2489},"filePathRelative":"后端开发/数据库/PostgreSQL/01_基础篇/03_索引体系.md"}`),s={name:`03_索引体系.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),r(`div`,null,[o[0]||=n(`<h1 id="索引体系" tabindex="-1"><a class="header-anchor" href="#索引体系"><span>索引体系</span></a></h1><div class="hint-container tip"><p class="hint-container-title">核心观点</p><p>PostgreSQL 提供了 6 种索引类型，覆盖了从等值查询到全文搜索、地理空间到向量检索的全场景。理解每种索引的适用场景，比盲目加索引重要一百倍。</p></div><h2 id="索引类型总览" tabindex="-1"><a class="header-anchor" href="#索引类型总览"><span>索引类型总览</span></a></h2>`,3),i(d,{code:``}),o[1]||=n(`<h2 id="b-tree-索引" tabindex="-1"><a class="header-anchor" href="#b-tree-索引"><span>B-Tree 索引</span></a></h2><p>B-Tree 是 PG 的默认索引类型，适用于等值查询、范围查询和排序：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 创建 B-Tree 索引（默认）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_users_email</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> users (email);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 等值查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> email </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;alice@example.com&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 范围查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#C678DD;">BETWEEN</span><span style="color:#98C379;"> &#39;2025-01-01&#39;</span><span style="color:#C678DD;"> AND</span><span style="color:#98C379;"> &#39;2025-06-30&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 排序（索引可避免 sort）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#C678DD;">DESC</span><span style="color:#C678DD;"> LIMIT</span><span style="color:#D19A66;"> 100</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 前缀 LIKE（仅前缀匹配可以用 B-Tree）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#C678DD;"> LIKE</span><span style="color:#98C379;"> &#39;张%&#39;</span><span style="color:#ABB2BF;">;    </span><span style="color:#7F848E;font-style:italic;">-- ✅ 可用索引</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#C678DD;"> LIKE</span><span style="color:#98C379;"> &#39;%明&#39;</span><span style="color:#ABB2BF;">;    </span><span style="color:#7F848E;font-style:italic;">-- ✗ 无法用索引</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 多列 B-Tree 索引（最左前缀原则）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_orders_user_date</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> orders (user_id, created_at);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 可以使用索引</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#56B6C2;">&gt;</span><span style="color:#98C379;"> &#39;2025-01-01&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✗ 无法使用索引（跳过了 user_id）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#56B6C2;">&gt;</span><span style="color:#98C379;"> &#39;2025-01-01&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="hash-索引" tabindex="-1"><a class="header-anchor" href="#hash-索引"><span>Hash 索引</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- Hash 索引：仅支持等值查询，不存储顺序</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_session_token</span><span style="color:#C678DD;"> ON</span><span style="color:#C678DD;"> sessions</span><span style="color:#C678DD;"> USING</span><span style="color:#C678DD;"> hash</span><span style="color:#ABB2BF;"> (token);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#C678DD;"> sessions</span><span style="color:#C678DD;"> WHERE</span><span style="color:#ABB2BF;"> token </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;abc123def456&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">慎用 Hash 索引</p><ul><li>只支持 <code>=</code> 查询，不支持范围、排序</li><li>PG 10 前的 Hash 索引不写 WAL，崩溃后需重建</li><li>PG 10+ 已修复 WAL 问题，但 B-Tree 在等值场景性能接近，没理由优先用 Hash</li><li>参考文档：<a href="https://www.postgresql.org/docs/16/indexes-types.html" target="_blank" rel="noopener noreferrer">Hash Indexes</a></li></ul></div><h2 id="gin-索引" tabindex="-1"><a class="header-anchor" href="#gin-索引"><span>GIN 索引</span></a></h2><p>GIN（Generalized Inverted Index，广义倒排索引）是 PG 最强大的索引类型之一，专为多值元素设计：</p>`,9),i(d,{code:``}),o[2]||=n(`<h3 id="gin-用于数组" tabindex="-1"><a class="header-anchor" href="#gin-用于数组"><span>GIN 用于数组</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 数组列 + GIN 索引</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> articles</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id    </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    title </span><span style="color:#C678DD;">text</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    tags  </span><span style="color:#C678DD;">text</span><span style="color:#E06C75;">[]</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#98C379;"> &#39;{}&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_articles_tags</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> articles </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> GIN (tags);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 包含查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> articles </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> tags @</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> ARRAY</span><span style="color:#E06C75;">[&#39;PostgreSQL&#39;]</span><span style="color:#ABB2BF;">;     </span><span style="color:#7F848E;font-style:italic;">-- 包含指定元素</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> articles </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> tags &amp;&amp; </span><span style="color:#C678DD;">ARRAY</span><span style="color:#E06C75;">[&#39;PostgreSQL&#39;, &#39;MySQL&#39;]</span><span style="color:#ABB2BF;">; </span><span style="color:#7F848E;font-style:italic;">-- 有交集</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> articles </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> tags </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">@ </span><span style="color:#C678DD;">ARRAY</span><span style="color:#E06C75;">[&#39;PostgreSQL&#39;, &#39;MySQL&#39;, &#39;Redis&#39;]</span><span style="color:#ABB2BF;">; </span><span style="color:#7F848E;font-style:italic;">-- 子集</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="gin-用于-jsonb" tabindex="-1"><a class="header-anchor" href="#gin-用于-jsonb"><span>GIN 用于 JSONB</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- JSONB 列 + GIN 索引</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> products</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id     </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    name</span><span style="color:#C678DD;">   text</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    attrs  jsonb </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#98C379;"> &#39;{}&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 默认 GIN 索引（支持所有 JSONB 操作符）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_products_attrs</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> products </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> GIN (attrs);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- jsonb_path_ops（更小更快，但仅支持 @&gt; 操作符）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_products_attrs_path</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> products </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> GIN (attrs jsonb_path_ops);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 对比</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 默认 GIN：支持 @&gt;, ?, ?|, ?&amp;  （索引更大）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- jsonb_path_ops：仅支持 @&gt;      （索引更小，查询更快）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- @&gt; 包含查询（两种 GIN 索引都支持）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> products </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> attrs @</span><span style="color:#56B6C2;">&gt;</span><span style="color:#98C379;"> &#39;{&quot;cpu&quot;: &quot;M3 Pro&quot;}&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 等价于 attrs-&gt;&gt;&#39;cpu&#39; = &#39;M3 Pro&#39;，但 @&gt; 可以用索引</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ? 键存在查询（仅默认 GIN 支持）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> products </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> attrs ? </span><span style="color:#98C379;">&#39;cpu&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 嵌套包含</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> products </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> attrs @</span><span style="color:#56B6C2;">&gt;</span><span style="color:#98C379;"> &#39;{&quot;specs&quot;: {&quot;screen&quot;: 14}}&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="gin-用于全文搜索" tabindex="-1"><a class="header-anchor" href="#gin-用于全文搜索"><span>GIN 用于全文搜索</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 中文全文搜索（需 zhparser 或 pg_jieba 扩展）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 这里用英文 tsvector 演示</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> documents</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id       </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    title    </span><span style="color:#C678DD;">text</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    content  </span><span style="color:#C678DD;">text</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    tsv      tsvector </span><span style="color:#C678DD;">GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">        setweight(to_tsvector(</span><span style="color:#98C379;">&#39;english&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#56B6C2;">coalesce</span><span style="color:#ABB2BF;">(title, </span><span style="color:#98C379;">&#39;&#39;</span><span style="color:#ABB2BF;">)), </span><span style="color:#98C379;">&#39;A&#39;</span><span style="color:#ABB2BF;">) ||</span></span>
<span class="line"><span style="color:#ABB2BF;">        setweight(to_tsvector(</span><span style="color:#98C379;">&#39;english&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#56B6C2;">coalesce</span><span style="color:#ABB2BF;">(content, </span><span style="color:#98C379;">&#39;&#39;</span><span style="color:#ABB2BF;">)), </span><span style="color:#98C379;">&#39;B&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    ) STORED</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_documents_tsv</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> documents </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> GIN (tsv);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 全文搜索</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> title, ts_rank(tsv, query) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> rank</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> documents, plainto_tsquery(</span><span style="color:#98C379;">&#39;english&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;PostgreSQL index optimization&#39;</span><span style="color:#ABB2BF;">) query</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> tsv @@ query</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> rank </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="gist-索引" tabindex="-1"><a class="header-anchor" href="#gist-索引"><span>GiST 索引</span></a></h2><p>GiST（Generalized Search Tree，通用搜索树）是一个框架，支持自定义数据类型的索引：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- GiST 用于范围类型</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> schedules</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id         </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    room_id    </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    time_slot  tstzrange </span><span style="color:#C678DD;">NOT NULL</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_schedules_time</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> schedules </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> GiST (time_slot);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 重叠查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> schedules </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> time_slot &amp;&amp; </span><span style="color:#98C379;">&#39;[2025-06-04 09:00, 2025-06-04 11:00)&#39;</span><span style="color:#ABB2BF;">::tstzrange;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 排除约束（防止重叠预订）</span></span>
<span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> schedules</span></span>
<span class="line"><span style="color:#C678DD;">    ADD</span><span style="color:#C678DD;"> CONSTRAINT</span><span style="color:#ABB2BF;"> no_overlap</span></span>
<span class="line"><span style="color:#ABB2BF;">    EXCLUDE </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> GiST (room_id </span><span style="color:#C678DD;">WITH</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;">, time_slot </span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> &amp;&amp;);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- GiST 用于 PostGIS 几何类型</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> EXTENSION </span><span style="color:#C678DD;">IF</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> EXISTS</span><span style="color:#ABB2BF;"> postgis;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> locations</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id   </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    name</span><span style="color:#C678DD;"> text</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    geo  </span><span style="color:#C678DD;">geometry</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">Point</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">4326</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_locations_geo</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> locations </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> GiST (geo);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 附近搜索</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> name</span><span style="color:#ABB2BF;">, ST_Distance(geo::</span><span style="color:#C678DD;">geography</span><span style="color:#ABB2BF;">, ST_MakePoint(</span><span style="color:#D19A66;">116</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">4</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">39</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">9</span><span style="color:#ABB2BF;">)::</span><span style="color:#C678DD;">geography</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> dist</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> locations</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> ST_DWithin(geo::</span><span style="color:#C678DD;">geography</span><span style="color:#ABB2BF;">, ST_MakePoint(</span><span style="color:#D19A66;">116</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">4</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">39</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">9</span><span style="color:#ABB2BF;">)::</span><span style="color:#C678DD;">geography</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">5000</span><span style="color:#ABB2BF;">)  </span><span style="color:#7F848E;font-style:italic;">-- 5km 内</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> dist;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="brin-索引" tabindex="-1"><a class="header-anchor" href="#brin-索引"><span>BRIN 索引</span></a></h2><p>BRIN（Block Range Index，块范围索引）适用于物理有序的大表，索引极小：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- BRIN 索引：记录每个数据块的值范围</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> access_logs</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id         </span><span style="color:#C678DD;">bigint</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    path</span><span style="color:#C678DD;">       text</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    method     </span><span style="color:#C678DD;">text</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    status</span><span style="color:#C678DD;">     integer</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    created_at </span><span style="color:#C678DD;">timestamptz</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#C678DD;"> now</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#C678DD;"> RANGE</span><span style="color:#ABB2BF;"> (created_at);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 时间序列数据天然有序，BRIN 索引效果极好</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_logs_created_at</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> access_logs </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> BRIN (created_at)</span></span>
<span class="line"><span style="color:#C678DD;">    WITH</span><span style="color:#ABB2BF;"> (pages_per_range </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 32</span><span style="color:#ABB2BF;">);  </span><span style="color:#7F848E;font-style:italic;">-- 每 32 个数据块记录一次范围</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 索引大小对比</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 1 亿行数据：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- B-Tree 索引：约 2-3 GB</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- BRIN 索引：约 2-5 MB   ← 小 1000 倍！</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看索引大小</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> indexrelname,</span></span>
<span class="line"><span style="color:#ABB2BF;">       pg_size_pretty(pg_relation_size(indexrelid)) </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> size</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_user_indexes</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> schemaname </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;public&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--  indexrelname          | size</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- -----------------------+-------</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--  idx_logs_created_at   | 56 kB    (BRIN)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--  idx_logs_path         | 2146 MB  (B-Tree)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">BRIN 的适用场景</p><ul><li><strong>时间序列数据</strong>：日志、监控、IoT 数据（按时间自然有序）</li><li><strong>自增 ID</strong>：插入顺序与 ID 顺序一致</li><li><strong>不适合</strong>：随机写入、值分布无序的列</li></ul><p>参考：<a href="https://www.postgresql.org/docs/16/brin.html" target="_blank" rel="noopener noreferrer">BRIN Indexes</a></p></div><h2 id="sp-gist-索引" tabindex="-1"><a class="header-anchor" href="#sp-gist-索引"><span>SP-GiST 索引</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- SP-GiST：支持非平衡数据结构（如前缀树、四叉树）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> phone_numbers</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id    </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    phone </span><span style="color:#C678DD;">text</span><span style="color:#C678DD;"> NOT NULL</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 前缀匹配（电话区号、IP 路由等）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_phone_prefix</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> phone_numbers </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> SP-GiST (phone text_pattern_ops);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> phone_numbers </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> phone </span><span style="color:#C678DD;">LIKE</span><span style="color:#98C379;"> &#39;010%&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="高级索引特性" tabindex="-1"><a class="header-anchor" href="#高级索引特性"><span>高级索引特性</span></a></h2><h3 id="部分索引-partial-index" tabindex="-1"><a class="header-anchor" href="#部分索引-partial-index"><span>部分索引（Partial Index）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 只索引活跃用户，减少索引大小</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_users_active_email</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> users (email)</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#C678DD;"> status</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;active&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 只索引未完成的订单</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_orders_pending</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> orders (created_at)</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#C678DD;"> status</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;pending&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查询必须满足 WHERE 条件才能使用部分索引</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> email </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;alice@example.com&#39;</span><span style="color:#C678DD;"> AND</span><span style="color:#C678DD;"> status</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;active&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 可以使用 idx_users_active_email</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> email </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;alice@example.com&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✗ 无法使用部分索引（不保证覆盖所有行）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="表达式索引" tabindex="-1"><a class="header-anchor" href="#表达式索引"><span>表达式索引</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 对计算结果建索引</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_users_lower_email</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> users (</span><span style="color:#56B6C2;">lower</span><span style="color:#ABB2BF;">(email));</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查询时使用相同的表达式才能命中</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users </span><span style="color:#C678DD;">WHERE</span><span style="color:#56B6C2;"> lower</span><span style="color:#ABB2BF;">(email) </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;alice@example.com&#39;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- ✅ 命中索引</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> email </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;Alice@Example.com&#39;</span><span style="color:#ABB2BF;">;          </span><span style="color:#7F848E;font-style:italic;">-- ✗ 无法命中</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 日期截断索引</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_orders_month</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> orders (date_trunc(</span><span style="color:#98C379;">&#39;month&#39;</span><span style="color:#ABB2BF;">, created_at));</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> date_trunc(</span><span style="color:#98C379;">&#39;month&#39;</span><span style="color:#ABB2BF;">, created_at) </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;2025-06-01&#39;</span><span style="color:#ABB2BF;">::</span><span style="color:#C678DD;">timestamptz</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="覆盖索引-covering-index-pg-11" tabindex="-1"><a class="header-anchor" href="#覆盖索引-covering-index-pg-11"><span>覆盖索引（Covering Index，PG 11+）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- INCLUDE 列存在索引中但不参与排序，用于 Index Only Scan</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_orders_user_covering</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> orders (user_id)</span></span>
<span class="line"><span style="color:#C678DD;">    INCLUDE</span><span style="color:#ABB2BF;"> (amount, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">, created_at);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查询只需访问索引，不需要回表</span></span>
<span class="line"><span style="color:#ABB2BF;">EXPLAIN (ANALYZE, BUFFERS)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> user_id, amount, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">, created_at</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Index Only Scan using idx_orders_user_covering</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="唯一索引" tabindex="-1"><a class="header-anchor" href="#唯一索引"><span>唯一索引</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 唯一索引保证列值唯一</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> UNIQUE INDEX</span><span style="color:#61AFEF;"> idx_users_email</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> users (email);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 部分唯一索引：允许 null 重复，非 null 唯一</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> UNIQUE INDEX</span><span style="color:#61AFEF;"> idx_users_phone</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> users (phone) </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> phone </span><span style="color:#C678DD;">IS NOT NULL</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 多列唯一</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> UNIQUE INDEX</span><span style="color:#61AFEF;"> idx_user_roles</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> user_roles (user_id, role_id);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="并发创建索引" tabindex="-1"><a class="header-anchor" href="#并发创建索引"><span>并发创建索引</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 普通创建索引会锁表（阻塞写入）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_orders_status</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> orders (</span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">);  </span><span style="color:#7F848E;font-style:italic;">-- ⚠️ 阻塞写入</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 并发创建：不锁表，但耗时更长</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> CONCURRENTLY</span><span style="color:#ABB2BF;"> idx_orders_status </span><span style="color:#C678DD;">ON</span><span style="color:#ABB2BF;"> orders (</span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 不阻塞读写，但创建过程中需要两次扫描表</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 唯一索引也可以并发创建</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> UNIQUE INDEX</span><span style="color:#61AFEF;"> CONCURRENTLY</span><span style="color:#ABB2BF;"> idx_users_phone </span><span style="color:#C678DD;">ON</span><span style="color:#ABB2BF;"> users (phone);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">CREATE INDEX CONCURRENTLY 注意事项</p><ul><li><strong>不能在事务中执行</strong>：<code>CONCURRENTLY</code> 不支持事务回滚</li><li><strong>可能失败</strong>：如果创建过程中有冲突的写入，索引会标记为 INVALID</li><li><strong>修复失败索引</strong>：<code>DROP INDEX idx_name;</code> 然后重新创建</li><li>参考文档：<a href="https://www.postgresql.org/docs/16/sql-createindex.html#SQL-CREATEINDEX-CONCURRENTLY" target="_blank" rel="noopener noreferrer">Concurrent Index Builds</a></li></ul></div><h2 id="explain-验证索引使用" tabindex="-1"><a class="header-anchor" href="#explain-验证索引使用"><span>EXPLAIN 验证索引使用</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 创建测试数据</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> orders</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id         </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    user_id    </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    status</span><span style="color:#C678DD;">     text</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#98C379;"> &#39;pending&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    amount     </span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    created_at </span><span style="color:#C678DD;">timestamptz</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#C678DD;"> now</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 不加索引：Seq Scan</span></span>
<span class="line"><span style="color:#ABB2BF;">EXPLAIN ANALYZE </span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Seq Scan on orders  (cost=0.00..1542.00 rows=1 width=40)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 加索引后：Index Scan</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_orders_user_id</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> orders (user_id);</span></span>
<span class="line"><span style="color:#ABB2BF;">EXPLAIN ANALYZE </span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Index Scan using idx_orders_user_id on orders  (cost=0.29..8.31 rows=1 width=40)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 覆盖索引：Index Only Scan</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_orders_user_covering</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> orders (user_id) </span><span style="color:#C678DD;">INCLUDE</span><span style="color:#ABB2BF;"> (amount, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#ABB2BF;">EXPLAIN ANALYZE </span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> user_id, amount, </span><span style="color:#C678DD;">status</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Index Only Scan using idx_orders_user_covering on orders</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 多行匹配：Bitmap Scan</span></span>
<span class="line"><span style="color:#ABB2BF;">EXPLAIN ANALYZE </span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">&lt;</span><span style="color:#D19A66;"> 100</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Bitmap Heap Scan on orders</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--   -&gt;  Bitmap Index Scan using idx_orders_user_id</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="postgrest-查询与索引" tabindex="-1"><a class="header-anchor" href="#postgrest-查询与索引"><span>PostgREST 查询与索引</span></a></h2><p><a href="https://github.com/PostgREST/postgrest" target="_blank" rel="noopener noreferrer">PostgREST</a> 将 HTTP 请求映射为 SQL 查询，索引直接决定 API 性能：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span># PostgREST API 请求</span></span>
<span class="line"><span>GET /orders?user_id=eq.1&amp;select=id,amount,status&amp;order=created_at.desc&amp;limit=10</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 等价 SQL</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> id, amount, </span><span style="color:#C678DD;">status</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 为 PostgREST 查询优化的索引</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_orders_user_date_desc</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> orders (user_id, created_at </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">    INCLUDE</span><span style="color:#ABB2BF;"> (amount, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Index Only Scan，覆盖查询全部列</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="面试技巧" tabindex="-1"><a class="header-anchor" href="#面试技巧"><span>面试技巧</span></a></h2><div class="hint-container tip"><p class="hint-container-title">面试高频问题</p><ol><li><p><strong>B-Tree 和 GIN 索引的区别？</strong></p><ul><li>B-Tree：一个 key 对应一行，适合标量值（=, &lt;, &gt;, BETWEEN）</li><li>GIN：一个 key 对应多行（倒排），适合多值元素（数组、JSONB、全文搜索）</li></ul></li><li><p><strong>什么时候用 BRIN？</strong></p><ul><li>数据量大（亿级）、物理有序（时间序列/自增 ID）、需要极小索引</li><li>BRIN 不存储具体值，只存数据块的范围摘要</li></ul></li><li><p><strong>部分索引有什么用？</strong></p><ul><li>减少索引大小（只索引需要的行）</li><li>索引条件越精确，索引越小，维护成本越低</li></ul></li><li><p><strong>CREATE INDEX CONCURRENTLY 的原理和风险？</strong></p><ul><li>分两阶段扫描，不持有排他锁</li><li>风险：创建失败会留下 INVALID 索引，需要手动清理</li></ul></li><li><p><strong>覆盖索引（INCLUDE）解决了什么问题？</strong></p><ul><li>Index Only Scan 避免回表</li><li>适合&quot;查少量列&quot;的高频查询</li></ul></li></ol></div><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li><a href="https://www.postgresql.org/docs/16/indexes-types.html" target="_blank" rel="noopener noreferrer">PostgreSQL 官方文档 - Index Types</a></li><li><a href="https://www.postgresql.org/docs/16/gin.html" target="_blank" rel="noopener noreferrer">PostgreSQL 官方文档 - GIN Indexes</a></li><li><a href="https://www.postgresql.org/docs/16/brin.html" target="_blank" rel="noopener noreferrer">PostgreSQL 官方文档 - BRIN Indexes</a></li><li><a href="https://www.postgresql.org/docs/16/indexes-expressional.html" target="_blank" rel="noopener noreferrer">PostgreSQL 官方文档 - Indexes on Expressions</a></li><li><a href="https://github.com/PostgREST/postgrest" target="_blank" rel="noopener noreferrer">PostgREST GitHub</a></li></ul>`,40)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};